HL=[('en','https://unbanz.com/meta-appeal-links-and-forms-directory/'),('fr','https://unbanz.com/fr/liens-officiels-appel-meta-instagram-facebook/'),('nl','https://unbanz.com/nl/officiele-bezwaarlinks-meta-instagram-facebook/'),('x-default','https://unbanz.com/meta-appeal-links-and-forms-directory/')]
FR=dict(lang='fr',slug='fr/liens-officiels-appel-meta-instagram-facebook',hreflang=HL,title='Liens officiels pour faire appel auprès de Meta (2026) : Instagram, Facebook, publicité',crumb='Liens officiels d’appel Meta',
 desc='Tous les liens officiels Instagram, Facebook et compte publicitaire Meta pour un compte désactivé, suspendu ou piraté, avec les recours en France. Vérifiés en novembre 2026.',
 h1='Les liens officiels pour faire appel auprès de Meta.',lede='Les pages officielles d’Instagram, de Facebook et de Meta pour un compte désactivé, suspendu, restreint ou piraté, et les recours possibles en France.',
 answer='<strong>Il n’existe pas de formulaire unique pour faire appel auprès de Meta.</strong> Un compte Instagram ou Facebook suspendu ou désactivé se conteste depuis le message affiché à la connexion, ou depuis l’Espace Comptes. Un compte piraté passe par instagram.com/hacked ou facebook.com/hacked. Un compte publicitaire se fait réexaminer dans Business Support Home, par un administrateur. Meta n’a pas de numéro de téléphone pour le service client. En France, des recours européens existent après l’appel interne. Meta prend la décision finale.',
 cards=[('Le message d’abord','L’appel part de l’écran affiché à la connexion.'),('Pas de téléphone','Meta n’a pas de numéro de support.'),('Gardez des preuves','Capture d’écran datée de chaque message.')],
 pre='<h2 id="quel-lien">Quel lien vous faut-il ?</h2><ul><li>« Nous avons suspendu votre compte » : faites appel depuis cet écran. Voir '+A('fr/compte-facebook-desactive-faire-appel','faire appel sur Facebook')+' et '+A('fr/compte-instagram-desactive-comment-recuperer','compte Instagram désactivé')+'.</li><li>Impossible de vous connecter, sans message : liens « compte piraté » ci-dessous. Voir '+A('fr/compte-instagram-pirate-que-faire','Instagram piraté')+' et '+A('fr/compte-facebook-pirate-que-faire','Facebook piraté')+'.</li><li>Publicités bloquées : Business Support Home. Voir '+A('fr/compte-publicitaire-meta-restreint','compte publicitaire restreint')+'.</li></ul>',
 sections=[('instagram','Instagram',[('Statut du compte','https://help.instagram.com/338481628002750','Dans l’application : Paramètres, puis Statut du compte. Contenus retirés, fonctions bloquées et, si proposé, demande de réexamen.'),('Comptes Instagram désactivés','https://help.instagram.com/366993040048856','La page d’aide de Meta. Si votre compte est désactivé, un message s’affiche à la connexion et l’appel part de là.'),('Compte piraté','https://www.instagram.com/hacked/','E-mail, téléphone ou mot de passe modifiés sans vous.'),('Espace Comptes','https://accountscenter.instagram.com/','Mot de passe, double authentification, appareils connectés, comptes liés.')]),
  ('facebook','Facebook',[('Compte personnel suspendu ou désactivé','https://www.facebook.com/help/103873106370583','Meta indique un délai d’appel de 180 jours après une suspension, variable selon les régions.'),('Compte piraté','https://www.facebook.com/hacked','Pour une prise de contrôle du compte.'),('Retrouver votre compte','https://www.facebook.com/login/identify','Réinitialisation du mot de passe et perte d’accès à l’e-mail ou au téléphone.'),('Assistance par téléphone','https://www.facebook.com/help/1088016719924954','Meta indique ne pas proposer de numéro de téléphone public pour le service client.')]),
  ('publicite','Comptes publicitaires',[('Compte publicitaire désactivé ou restreint','https://www.facebook.com/business/help/422289316306981','Sur ordinateur : Business Support Home, le compte concerné, puis « Ce que vous pouvez faire ».'),('Business Support Home','https://business.facebook.com/accountquality','Restrictions des comptes publicitaires, Pages et portefeuilles business, et bouton de réexamen.')]),
  ('france','Recours et signalements en France et en Europe',[('Appeals Centre Europe','https://www.appealscentre.eu/','Organe indépendant de règlement extrajudiciaire prévu par le règlement européen sur les services numériques (DSA), après l’appel interne.'),('Arcom','https://www.arcom.fr/','Coordinateur pour les services numériques en France.'),('Cybermalveillance.gouv.fr','https://www.cybermalveillance.gouv.fr/','Assistance aux victimes de piratage de compte et conseils officiels.'),('Pharos','https://www.internet-signalement.gouv.fr/','Plateforme officielle de signalement des contenus illicites en ligne.'),('CNIL','https://www.cnil.fr/','Autorité de protection des données, pour l’accès à vos données personnelles.')])],
 post=['<h2 id="avant">Avant d’utiliser un lien</h2><ol><li>Faites une capture d’écran du message complet, avec la date.</li><li>Utilisez votre téléphone ou ordinateur habituel, sans VPN.</li><li>Faites appel une seule fois, avec des phrases simples.</li><li>Ne créez pas de nouveau compte pendant l’attente.</li><li>Il n’existe pas de « lien d’appel privé ».</li></ol>',
  '<h2 id="email">Peut-on écrire à Meta par e-mail ?</h2><p>Non. Meta ne traite pas les appels par e-mail. Une lettre adressée à Meta et envoyée à un service indépendant comme Unbanz n’arrive pas chez Meta. Collez votre texte, en version courte, dans le champ d’appel de l’application.</p>'],
 related=A('fr/droit-de-recours-dsa-meta','recours DSA')+', '+A('fr/appeals-centre-europe-instagram-facebook','Appeals Centre Europe')+', '+A('fr/compte-pirate-porter-plainte-signaler','porter plainte pour un compte piraté')+', '+A('meta-appeal-links-and-forms-directory','version anglaise')+'.',
 faqs=[('Existe-t-il un formulaire officiel unique pour faire appel auprès de Meta ?','Non. L’appel part du message affiché à la connexion ou de l’Espace Comptes. Les comptes publicitaires passent par Business Support Home.'),('Meta a-t-il un numéro de téléphone en France ?','Meta indique ne pas proposer de numéro public pour le service client. Méfiez-vous des numéros se présentant comme le support Meta.'),('Que faire après un refus ?','En Europe, vous pouvez saisir un organe de règlement extrajudiciaire comme Appeals Centre Europe.'),('Dois-je donner mon mot de passe ?','Non. Votre mot de passe et vos codes restent chez vous.')])
NL=dict(lang='nl',slug='nl/officiele-bezwaarlinks-meta-instagram-facebook',hreflang=HL,title='Officiële bezwaarlinks van Meta (2026): Instagram, Facebook, advertenties',crumb='Officiële bezwaarlinks Meta',
 desc='Alle officiële links van Instagram, Facebook en Meta-advertentieaccounts voor een uitgeschakeld, opgeschort of gehackt account, plus de mogelijkheden in Nederland. Gecontroleerd in november 2026.',
 h1='De officiële links om bezwaar te maken bij Meta.',lede='De officiële pagina’s van Instagram, Facebook en Meta voor een uitgeschakeld, opgeschort, beperkt of gehackt account, en wat je in Nederland daarna nog kunt doen.',
 answer='<strong>Er is geen los bezwaarformulier van Meta.</strong> Bezwaar tegen een opgeschort of uitgeschakeld Instagram- of Facebookaccount maak je vanuit de melding die je ziet bij het inloggen, of via het Accountcentrum. Bij een gehackt account begin je op instagram.com/hacked of facebook.com/hacked. Een advertentieaccount laat een beheerder opnieuw beoordelen in Business Support Home. Meta heeft geen telefoonnummer voor klantenservice. In Nederland zijn er na het interne bezwaar ook Europese mogelijkheden. Meta neemt het eindbesluit.',
 cards=[('Eerst de melding','Het bezwaar start vanaf het scherm bij het inloggen.'),('Geen telefoon','Meta heeft geen supportnummer.'),('Bewaar bewijs','Maak een screenshot met datum.')],
 pre='<h2 id="welke-link">Welke link heb je nodig?</h2><ul><li>“We hebben je account opgeschort”: maak bezwaar vanaf dat scherm. Zie '+A('nl/facebook-account-uitgeschakeld-bezwaar','bezwaar tegen Facebook')+' en '+A('nl/instagram-account-terugkrijgen','Instagram-account terugkrijgen')+'.</li><li>Je kunt niet inloggen en ziet geen melding: de links voor gehackte accounts hieronder. Zie '+A('nl/instagram-account-gehackt','Instagram gehackt')+' en '+A('nl/facebook-account-gehackt','Facebook gehackt')+'.</li><li>Advertenties gestopt: Business Support Home. Zie '+A('nl/advertentieaccount-terugkrijgen','advertentieaccount terugkrijgen')+'.</li></ul>',
 sections=[('instagram','Instagram',[('Accountstatus','https://help.instagram.com/338481628002750','In de app: Instellingen, dan Accountstatus. Verwijderde berichten, geblokkeerde functies en, als die er is, de knop om een beoordeling aan te vragen.'),('Uitgeschakelde Instagram-accounts','https://help.instagram.com/366993040048856','De hulppagina van Meta. Is je account uitgeschakeld, dan zie je een melding bij het inloggen en begint het bezwaar daar.'),('Gehackt account','https://www.instagram.com/hacked/','E-mail, telefoonnummer of wachtwoord gewijzigd zonder jou.'),('Accountcentrum','https://accountscenter.instagram.com/','Wachtwoord, tweestapsverificatie, ingelogde apparaten en gekoppelde accounts.')]),
  ('facebook','Facebook',[('Persoonlijk account opgeschort of uitgeschakeld','https://www.facebook.com/help/103873106370583','Meta noemt een bezwaartermijn van 180 dagen na een opschorting, afhankelijk van de regio.'),('Gehackt account','https://www.facebook.com/hacked','Voor een overgenomen account.'),('Je account zoeken','https://www.facebook.com/login/identify','Wachtwoord herstellen en geen toegang meer tot e-mail of telefoon.'),('Telefonische ondersteuning','https://www.facebook.com/help/1088016719924954','Meta zegt geen openbaar telefoonnummer voor klantenservice te hebben.')]),
  ('advertenties','Advertentieaccounts',[('Uitgeschakeld of beperkt advertentieaccount','https://www.facebook.com/business/help/422289316306981','Op een computer: Business Support Home, het betreffende account, dan “Wat je kunt doen”.'),('Business Support Home','https://business.facebook.com/accountquality','Beperkingen van advertentieaccounts, Pagina’s en bedrijfsportfolio’s, met de knop voor een nieuwe beoordeling.')]),
  ('nederland','Mogelijkheden in Nederland en Europa',[('Appeals Centre Europe','https://www.appealscentre.eu/','Onafhankelijke geschillenbeslechting onder de Europese digitaledienstenverordening (DSA), na het bezwaar bij Meta.'),('ACM','https://www.acm.nl/','De Autoriteit Consument & Markt, de Nederlandse coördinator voor digitale diensten.'),('Fraudehelpdesk','https://www.fraudehelpdesk.nl/','Advies en melding bij oplichting, ook als een gehackt account is gebruikt voor fraude.'),('Autoriteit Persoonsgegevens','https://www.autoriteitpersoonsgegevens.nl/','Toezichthouder voor privacy, voor vragen over inzage in je gegevens.')])],
 post=['<h2 id="voordat">Voordat je een link gebruikt</h2><ol><li>Maak een screenshot van de volledige melding, met datum.</li><li>Gebruik je gewone telefoon of computer, zonder VPN.</li><li>Maak één keer bezwaar, in duidelijke woorden.</li><li>Maak geen nieuw account aan terwijl je wacht.</li><li>Een “privé bezwaarlink” bestaat niet.</li></ol>',
  '<h2 id="email">Kun je Meta mailen?</h2><p>Nee. Meta behandelt bezwaren niet per e-mail. Een brief aan Meta die je naar een onafhankelijke dienst zoals Unbanz stuurt, komt niet bij Meta terecht. Plak een korte versie van je tekst in het bezwaarveld in de app.</p>'],
 related=A('nl/dsa-recht-op-beroep-meta','DSA-recht op beroep')+', '+A('nl/appeals-centre-europe-instagram-facebook','Appeals Centre Europe')+', '+A('nl/bezwaar-maken-via-accountcentrum','bezwaar via het Accountcentrum')+', '+A('nl/gehackt-account-aangifte-doen','aangifte doen bij een gehackt account')+', '+A('meta-appeal-links-and-forms-directory','Engelse versie')+'.',
 faqs=[('Is er één officieel bezwaarformulier van Meta?','Nee. Het bezwaar begint bij de melding bij het inloggen of in het Accountcentrum. Advertentieaccounts gaan via Business Support Home.'),('Heeft Meta een telefoonnummer in Nederland?','Meta zegt geen openbaar telefoonnummer voor klantenservice te hebben. Wees voorzichtig met nummers die zich als Meta-support voordoen.'),('Wat als mijn bezwaar is afgewezen?','In de EU kun je daarna naar een buitengerechtelijke geschilleninstantie zoals Appeals Centre Europe.'),('Moet ik mijn wachtwoord delen?','Nee. Je wachtwoord en inlogcodes blijven bij jou.')])
